/* Carousel behavior — generated by sitereal. A hand edit here is kept: sitereal asks before writing over it. */
(() => {
  const P = (name) => '[data-carousel-part="' + name + '"]';
  const REDUCED = () => matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* Only the parts of *this* carousel: a carousel inside a slide of another
     one is rare and is still allowed to work. */
  const own = (root, name) =>
    [...root.querySelectorAll(P(name))].filter((el) => el.closest(P('carousel')) === root);

  /* Which of the three flows, asked of the CSS rather than of an attribute.
     The prestyle class declares it, so switching the look switches the
     behavior and there is one place it is written down. */
  const flowOf = (root) => {
    const v = getComputedStyle(root).getPropertyValue('--carousel-flow').trim();
    return v === 'fade' || v === 'marquee' ? v : 'slides';
  };

  const num = (root, attr, fallback) => {
    const v = parseFloat(root.getAttribute(attr) || '');
    return Number.isFinite(v) ? v : fallback;
  };

  /* ---- the shared part: what a step is, and who says where we are ------ */

  function wireSteps(root, track, flow) {
    const wraps = root.hasAttribute('data-carousel-loop');
    const prev = own(root, 'prev');
    const next = own(root, 'next');
    const dotStrips = own(root, 'dots');
    const slides = () => own(root, 'slide').filter((s) => !s.hasAttribute('data-carousel-clone'));

    let index = 0;

    /* Where the scroller actually is, rather than where we last put it —
       a finger or a trackpad moves it without asking us. */
    const readIndex = () => {
      if (flow === 'fade') return index;
      const list = slides();
      if (!list.length) return 0;
      let best = 0;
      let dist = Infinity;
      for (let i = 0; i < list.length; i += 1) {
        const d = Math.abs((list[i].offsetLeft - track.offsetLeft) - track.scrollLeft);
        if (d < dist) { dist = d; best = i; }
      }
      return best;
    };

    const go = (i, opts = {}) => {
      const list = slides();
      if (!list.length) return;
      const wrap = opts.wrap ?? wraps;
      let target = i;
      if (target < 0) target = wrap ? list.length - 1 : 0;
      if (target > list.length - 1) target = wrap ? 0 : list.length - 1;
      index = target;
      if (flow === 'fade') {
        for (const s of list) s.toggleAttribute('data-carousel-active', s === list[target]);
      } else {
        track.scrollTo({
          left: list[target].offsetLeft - track.offsetLeft,
          behavior: REDUCED() ? 'auto' : 'smooth',
        });
      }
      sync();
    };

    /* One place decides what the controls say, so a step taken by an arrow,
       by a dot, by autoplay and by a finger all leave the same state behind. */
    function sync() {
      const list = slides();
      const at = readIndex();
      index = at;
      /* The ends, measured rather than counted: with several slides across,
         the last one is reachable long before it is the "current" one. */
      const atStart = flow === 'fade' ? at === 0 : track.scrollLeft <= 1;
      const atEnd = flow === 'fade'
        ? at === list.length - 1
        : track.scrollLeft >= track.scrollWidth - track.clientWidth - 1;
      for (const b of prev) b.disabled = !wraps && atStart;
      for (const b of next) b.disabled = !wraps && atEnd;
      for (const strip of dotStrips) {
        const dots = [...strip.children];
        for (let i = 0; i < dots.length; i += 1) {
          if (i === at) dots[i].setAttribute('aria-current', 'true');
          else dots[i].removeAttribute('aria-current');
        }
      }
    }

    for (const b of prev) b.addEventListener('click', () => go(index - 1));
    for (const b of next) b.addEventListener('click', () => go(index + 1));

    /* One dot per slide, made here because there are as many of them as there
       is data — a page whose slides come out of a collection does not know
       how many it has until it is built. They are styled by the strip's own
       rule, in your stylesheet, like everything else. */
    for (const strip of dotStrips) {
      strip.textContent = '';
      slides().forEach((_, i) => {
        const dot = document.createElement('button');
        dot.type = 'button';
        dot.setAttribute('builder-data-element', 'carousel-dot');
        dot.setAttribute('data-carousel-part', 'dot');
        dot.setAttribute('aria-label', (strip.getAttribute('data-dot-label') || 'Go to slide %n').replace(/%n/g, String(i + 1)));
        dot.addEventListener('click', () => go(i));
        strip.append(dot);
      });
    }

    if (flow !== 'fade') {
      let queued = false;
      track.addEventListener('scroll', () => {
        if (queued) return;
        queued = true;
        requestAnimationFrame(() => { queued = false; sync(); });
      }, { passive: true });
    }

    if (flow === 'fade') go(0);
    else sync();
    /* A resize changes how many slides fit, which changes which one is at the
       end — and so which arrow is disabled. */
    addEventListener('resize', sync, { passive: true });

    return { go, at: () => index, count: () => slides().length };
  }

  /* ---- autoplay ---------------------------------------------------------

     It wraps whatever the loop attribute says: an autoplay that stopped dead
     at the last slide is a carousel that looks broken. It never runs under
     reduced motion, it stops while the pointer is in it or the keyboard is,
     and it stops while the tab is in the background — a carousel that
     advanced nine times behind your back is nine slides you did not see. */

  function wireAutoplay(root, steps) {
    const every = Number(root.getAttribute('data-carousel-autoplay') || '');
    if (!Number.isFinite(every) || every <= 0 || REDUCED()) return;
    let timer = 0;
    let held = 0;
    const tick = () => { if (!held && !document.hidden) steps.go(steps.at() + 1, { wrap: true }); };
    const start = () => { stop(); timer = setInterval(tick, Math.max(1200, every)); };
    const stop = () => { if (timer) clearInterval(timer); timer = 0; };
    const hold = (on) => { held = Math.max(0, held + (on ? 1 : -1)); };
    root.addEventListener('pointerenter', () => hold(true));
    root.addEventListener('pointerleave', () => hold(false));
    root.addEventListener('focusin', () => hold(true));
    root.addEventListener('focusout', () => hold(false));
    document.addEventListener('visibilitychange', () => { if (document.hidden) stop(); else start(); });
    start();
  }

  /* ---- the marquee ------------------------------------------------------

     A ticker is not a series of steps, so none of the above applies to it.
     The row is cloned once so there is something to scroll into, and
     scrollLeft is written a frame at a time — no CSS animation, because the
     thing being moved is the scroll position and a transform on the scroller
     would move the scroller.

     Under reduced motion it does neither: no clones, no frames. What is left
     is the markup as written, which is a row you can scroll yourself. */

  function wireMarquee(root, track) {
    if (REDUCED()) return;
    const originals = own(root, 'slide');
    if (!originals.length) return;

    /* One lap is the original row plus the gap after it — measured as the
       distance to the first copy of it, so it stays right whatever a slide's
       width turns out to be. */
    const lap = () => {
      const firstClone = track.querySelector('[data-carousel-clone]');
      return firstClone ? firstClone.offsetLeft - track.children[0].offsetLeft : track.scrollWidth;
    };

    const copyRow = () => {
      for (const el of originals) {
        const copy = el.cloneNode(true);
        copy.setAttribute('data-carousel-clone', '');
        copy.setAttribute('aria-hidden', 'true');
        for (const f of copy.querySelectorAll('a[href], button, input, select, textarea')) f.tabIndex = -1;
        track.append(copy);
      }
    };

    /* Always at least one copy, and then as many as it takes for a lap plus a
       trackful to exist. Both halves matter: without the first there is
       nothing to scroll into and nothing to measure a lap by, and without the
       second the seam shows — the wrap happens one lap in, so the track has to
       still be full at that point. A row that already overflows is *not*
       enough on its own, which is what a "does it overflow?" test got wrong. */
    const fill = () => {
      for (const c of [...track.children].filter((el) => el.hasAttribute('data-carousel-clone'))) c.remove();
      copyRow();
      let guard = 0;
      while (track.scrollWidth < track.clientWidth + lap() && guard < 20) { copyRow(); guard += 1; }
    };
    fill();

    let held = 0;
    const hold = (on) => { held = Math.max(0, held + (on ? 1 : -1)); };
    root.addEventListener('pointerenter', () => hold(true));
    root.addEventListener('pointerleave', () => hold(false));
    root.addEventListener('focusin', () => hold(true));
    root.addEventListener('focusout', () => hold(false));

    const speed = num(root, 'data-carousel-speed', 60);
    const back = root.hasAttribute('data-carousel-reverse');
    if (back) track.scrollLeft = lap();

    let last = 0;
    const frame = (now) => {
      const dt = last ? Math.min(64, now - last) : 0;
      last = now;
      if (!held && !document.hidden && dt) {
        const span = lap();
        let x = track.scrollLeft + (back ? -1 : 1) * speed * (dt / 1000);
        if (span > 0) {
          if (x >= span) x -= span;
          if (x < 0) x += span;
        }
        track.scrollLeft = x;
      }
      requestAnimationFrame(frame);
    };
    requestAnimationFrame(frame);

    addEventListener('resize', fill, { passive: true });
  }

  /* ---- one carousel ----------------------------------------------------- */

  function init(root) {
    if (root.hasAttribute('data-carousel-ready')) return;
    const track = own(root, 'track')[0];
    if (!track) return;
    root.setAttribute('data-carousel-ready', '');

    const flow = flowOf(root);
    if (flow === 'marquee') { wireMarquee(root, track); return; }
    const steps = wireSteps(root, track, flow);
    wireAutoplay(root, steps);
  }

  const scan = (scope) => {
    for (const root of (scope || document).querySelectorAll(P('carousel'))) init(root);
  };

  if (document.readyState === 'loading') addEventListener('DOMContentLoaded', () => scan());
  else scan();

  document.__siterealCarousel = { scan };
})();
